tools.example:
carrier = nrCarrierConfig(NCellID=42, SubcarrierSpacing=30, NSizeGrid=51);
info = nrOFDMInfo(carrier);   % SampleRate, Nfft, SymbolsPerSlot ...
grid = nrResourceGrid(carrier, 2);   % 2 antenna ports

pdsch = nrPDSCHConfig(Modulation='64QAM', NumLayers=2, PRBSet=0:50, SymbolAllocation=[2 12]);
pdsch.DMRS.DMRSAdditionalPosition = 1;
[ind, info] = nrPDSCHIndices(carrier, pdsch);   % info.G = number of coded bits

[pdschInd, pdschInfo] = nrPDSCHIndices(carrier, pdsch);
grid = nrResourceGrid(carrier, pdsch.NumLayers);
grid(pdschInd) = pdschSymbols;

encodeDLSCH = nrDLSCH(TargetCodeRate=0.5);
setTransportBlock(encodeDLSCH, randi([0 1], tbs, 1));
cw = encodeDLSCH(pdsch.Modulation, pdsch.NumLayers, pdschInfo.G, 0);   % RV 0
sym = nrPDSCH(carrier, pdsch, cw);

[eqSym, csi] = nrEqualizeMMSE(rxSym, Hest, nVar);
[dlschLLRs, rxSymbols] = nrPDSCHDecode(carrier, pdsch, eqSym, nVar);
decodeDLSCH = nrDLSCHDecoder(TargetCodeRate=0.5, TransportBlockLength=tbs);
[bits, blkerr] = decodeDLSCH(dlschLLRs, pdsch.Modulation, pdsch.NumLayers, 0);

dmrsSym = nrPDSCHDMRS(carrier, pdsch);
dmrsInd = nrPDSCHDMRSIndices(carrier, pdsch);
grid(dmrsInd) = dmrsSym;
% receiver:
[Hest, nVar] = nrChannelEstimate(carrier, rxGrid, dmrsInd, dmrsSym);

tbs = nrTBS(pdsch.Modulation, pdsch.NumLayers, numel(pdsch.PRBSet), pdschInfo.NREPerPRB, 0.5);
encodeDLSCH = nrDLSCH(TargetCodeRate=0.5);
setTransportBlock(encodeDLSCH, randi([0 1], tbs, 1));
cw = encodeDLSCH(pdsch.Modulation, pdsch.NumLayers, pdschInfo.G, 0);

decodeDLSCH = nrDLSCHDecoder(TargetCodeRate=0.5, TransportBlockLength=tbs, MaximumLDPCIterationCount=12);
[rxBits, blkerr] = decodeDLSCH(dlschLLRs, pdsch.Modulation, pdsch.NumLayers, 0);
if ~blkerr, resetSoftBuffer(decodeDLSCH, 0); end

pusch = nrPUSCHConfig(Modulation='16QAM', NumLayers=1, PRBSet=0:24, TransformPrecoding=true);
[ind, info] = nrPUSCHIndices(carrier, pusch);
encodeULSCH = nrULSCH(TargetCodeRate=0.4);
setTransportBlock(encodeULSCH, randi([0 1], nrTBS(pusch.Modulation, 1, 25, info.NREPerPRB, 0.4), 1));
cw = encodeULSCH(pusch.Modulation, 1, info.G, 0);
sym = nrPUSCH(carrier, pusch, cw);

[txWaveform, ofdmInfo] = nrOFDMModulate(carrier, grid);
fs = ofdmInfo.SampleRate;
rxGrid = nrOFDMDemodulate(carrier, rxWaveform);

offset = nrTimingEstimate(carrier, rxWaveform, dmrsInd, dmrsSym);
rxWaveform = rxWaveform(1+offset:end, :);
rxGrid = nrOFDMDemodulate(carrier, rxWaveform);

tdl = nrTDLChannel(DelayProfile='TDL-C', DelaySpread=300e-9, MaximumDopplerShift=50, NumTransmitAntennas=2, NumReceiveAntennas=2);
tdl.SampleRate = ofdmInfo.SampleRate;
[rxWave, pathGains, sampleTimes] = tdl(txWaveform);
pathFilters = getPathFilters(tdl);
[offset, mag] = nrPerfectTimingEstimate(pathGains, pathFilters);
Hest = nrPerfectChannelEstimate(carrier, pathGains, pathFilters, offset, sampleTimes);

cdl = nrCDLChannel(DelayProfile='CDL-B', DelaySpread=100e-9, MaximumDopplerShift=30, CarrierFrequency=3.5e9);
cdl.TransmitAntennaArray.Size = [2 4 2 1 1];   % 16 elements, dual-polarized
cdl.ReceiveAntennaArray.Size = [1 2 2 1 1];
cdl.SampleRate = fs;
[rxWave, pathGains, sampleTimes] = cdl(txWave);
displayChannel(cdl)

pathFilters = getPathFilters(tdl);
[offset, mag] = nrPerfectTimingEstimate(pathGains, pathFilters);
Hest = nrPerfectChannelEstimate(carrier, pathGains, pathFilters, offset, sampleTimes);
nVar = 10^(-snrdB/10);

[Hest, nVar] = nrChannelEstimate(carrier, rxGrid, dmrsInd, dmrsSym, CDMLengths=pdsch.DMRS.CDMLengths);
[pdschRx, pdschHest] = nrExtractResources(pdschInd, rxGrid, Hest);
[eq, csi] = nrEqualizeMMSE(pdschRx, pdschHest, nVar);

[eqSym, csi] = nrEqualizeMMSE(pdschRx, pdschHest, nVar);
[llrs, rxSymbols] = nrPDSCHDecode(carrier, pdsch, eqSym, nVar);
csi = nrLayerDemap(csi);
llrs{1} = llrs{1} .* repmat(csi{1}.', pdschInfo.Qm, 1);   % per shipped example

tb = randi([0 1], 5000, 1);
tbIn = nrCRCEncode(tb, '24A');
cbs = nrCodeBlockSegmentLDPC(tbIn, 1);
enc = nrLDPCEncode(cbs, 1);
rm = nrRateMatchLDPC(enc, 12000, 0, 'QPSK', 1);

K = 56; E = 864; L = 8;
msg = randi([0 1], K, 1);
enc = nrPolarEncode(msg, E);
mod = nrSymbolModulate(nrRateMatchPolar(enc, K, E), 'QPSK');
% receiver:
llr = nrSymbolDemodulate(mod + 0.3*randn(size(mod)), 'QPSK', 0.09);
dec = nrPolarDecode(nrRateRecoverPolar(llr, K, numel(enc)), K, E, L);

ncellid = 17;
ssbGrid = zeros(240, 4);
ssbGrid(nrPSSIndices) = nrPSS(ncellid);
ssbGrid(nrSSSIndices) = nrSSS(ncellid);
% cell search: correlate received waveform with each of the 3 PSS via nrTimingEstimate

mib = randi([0 1], 24, 1);
cw = nrBCH(mib, 0, 0, 8, 0, ncellid);
pbchSym = nrPBCH(cw, ncellid, 0);
ssbGrid(nrPBCHIndices(ncellid)) = pbchSym;
ssbGrid(nrPBCHDMRSIndices(ncellid)) = nrPBCHDMRS(ncellid, 0);

cinit = mod(2^15*(1+1) + ncellid, 2^31);
c = nrPRBS(cinit, 1000);
scrambled = xor(bits, c);

bits = randi([0 1], 6000, 1);
sym = nrSymbolModulate(bits, '64QAM');
rx = awgn(sym, 20, 'measured');
llr = nrSymbolDemodulate(rx, '64QAM', 10^(-20/10));
ber = mean((llr < 0) ~= bits)

cfg = nrDLCarrierConfig(FrequencyRange='FR1', ChannelBandwidth=40, NumSubframes=10);
cfg.SCSCarriers = {nrSCSCarrierConfig(SubcarrierSpacing=30, NSizeGrid=106)};
cfg.BandwidthParts = {nrWavegenBWPConfig(SubcarrierSpacing=30, NSizeBWP=106)};
cfg.PDSCH = {nrWavegenPDSCHConfig(Modulation='256QAM', PRBSet=0:105, TargetCodeRate=0.7)};
[wave, info] = nrWaveformGenerator(cfg);
fs = info.ResourceGrids(1).Info.SampleRate;

cfg = nrDLCarrierConfig(ChannelBandwidth=20, NumSubframes=2);
cfg.SSBurst.BlockPattern = 'Case B';
cfg.PDSCH{1}.Modulation = 'QPSK';
[wave, info] = nrWaveformGenerator(cfg);

rmc = lteRMCDL('R.12');
rmc.PDSCH.Modulation = {'64QAM'};
rmc.TotSubframes = 20;
[waveform, grid, rmc] = lteRMCDLTool(rmc, [1; 0; 0; 1]);

[wave, grid, cfg] = lteRMCDLTool('R.6', [1;0;1;1], 'FDD', 10);
fs = cfg.SamplingRate;
rxGrid = lteOFDMDemodulate(cfg, wave);

chcfg = struct('DelayProfile','EVA','DopplerFreq',70,'NRxAnts',2,'MIMOCorrelation','Low', ...
               'SamplingRate',cfg.SamplingRate,'Seed',1,'InitTime',0,'NTerms',16, ...
               'ModelType','GMEDS','NormalizeTxAnts','On','NormalizePathGains','On','InitPhase','Random');
[rxWave, chInfo] = lteFadingChannel(chcfg, [wave; zeros(25, size(wave,2))]);

enb = lteRMCDL('R.4');
grid = lteDLResourceGrid(enb);
grid(lteCellRSIndices(enb)) = lteCellRS(enb);
[wave, info] = lteOFDMModulate(enb, grid);
rxGrid = lteOFDMDemodulate(enb, wave);

cec = struct('FreqWindow',9,'TimeWindow',9,'InterpType','cubic','PilotAverage','UserDefined','InterpWindow','Centered','InterpWinSize',1);
[hest, nest] = lteDLChannelEstimate(enb, cec, rxGrid);
[pdschRx, pdschHest] = lteExtractResources(pdschInd, rxGrid, hest);
[cws, syms] = ltePDSCHDecode(enb, pdsch, pdschRx, pdschHest, nest);

enb = struct('NDLRB', 6, 'DuplexMode', 'FDD', 'CyclicPrefix', 'Normal');
foff = lteFrequencyOffset(enb, rx);
rx = lteFrequencyCorrect(enb, rx, foff);
[cellID, offset] = lteCellSearch(enb, rx);
rx = rx(1+offset:end, :);
